entries[66] = { ["name"] = "Unsichtbarkeit", ["text"] = "3% von Grundmana\nSofort 5 min Abklingzeit\nLässt Euch im Verlauf von 3 Sek. bis zur Unsichtbarkeit verblassen und verringert mit jeder Sekunde die Bedrohung. Während Ihr unsichtbar seid, könnt Ihr von Gegnern nicht als Ziel gewählt werden. Hält 20 Sek. lang an. Wenn Ihr Aktionen ausführt, wird der Effekt abgebrochen." }
entries[71] = { ["name"] = "Frontkämpfer", ["text"] = "Ihr seid vom Kampf gestählt, was Eure Ausdauer um 40% erhöht und Eure Rüstung um 70% Eurer Stärke erhöht.\n(500ms Abklingzeit)" }
entries[75] = { ["name"] = "Automatischer Schuss", ["text"] = "40 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt automatisch auf das Ziel, bis die Aktion abgebrochen wird." }
