entries[96] = { ["name"] = "Zerstückeln", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nErhöht den Schaden Eures nächsten Nahkampfangriffes um 100 und lässt das Ziel bluten." }
entries[99] = { ["name"] = "Erschütterndes Gebrüll", ["text"] = "Sofort 30 sek. Abklingzeit\nVerwandelt Euch in Bärengestalt und ruft den Geist Ursols an, um ein ohrenbetäubendes Gebrüll auszustoßen, das alle Gegner innerhalb von 10 Metern 3 Sek. lang handlungsunfähig macht. Schaden kann den Effekt beenden." }
entries[100] = { ["name"] = "Sturmangriff", ["text"] = "8 - 25 Meter Reichweite\nSofort 20 sek. Abklingzeit\n1 Aufladung\nStürmt auf einen Gegner zu, verursacht (21% der Angriffskraft) körperlichen Schaden und macht ihn für 1 Sek. bewegungsunfähig. [ Kriegstreiber : Zusätzlich wird er für bis Abbruch betäubt ]\nErzeugt 20 Wut." }
entries[101] = { ["name"] = "Straucheln", ["text"] = "15 Energie Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nBringt den humanoiden Feind zu Fall, wobei 6 Schaden verursacht werden und der Gegner 3 Sek. lang am Boden liegt. Gewährt 1 Combopunkt." }
entries[107] = { ["name"] = "Blocken", ["text"] = "Benötigt Schild\nGewährt die Chance, Nahkampfattacken und Distanzangriffe des Feindes zu blocken." }
entries[110] = { ["name"] = "Critter Tracking (INTERNAL)" }
entries[111] = { ["name"] = "Zeitverzerrung", ["text"] = "Sofort" }
entries[113] = { ["name"] = "Eisketten", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nSchlingt eisige Ketten um das Ziel, welche es 6 Sek. lang an Ort und Stelle festhalten." }
entries[116] = { ["name"] = "Frostblitz", ["text"] = "2% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Frostblitz auf den Gegner, der (106.37% der Zaubermacht) Frostschaden verursacht und seine Bewegungsgeschwindigkeit 8 Sek. lang um 50% verringert." }
entries[118] = { ["name"] = "Verwandlung", ["text"] = "4% von Grundmana 30 Meter Reichweite\nWirken in 1.7 sek.\nVerwandelt den Gegner in ein Schaf, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden kann den Effekt abbrechen. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Wildtieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]" }
entries[120] = { ["name"] = "Kältekegel", ["text"] = "4% von Grundmana\nSofort 12 sek. Abklingzeit\nZiele in einem kegelförmigen Bereich vor Euch erleiden (43.125% der Zaubermacht) Frostschaden und ihre Bewegungsgeschwindigkeit ist 5 Sek. lang um 70% verringert ." }
entries[122] = { ["name"] = "Frostnova", ["text"] = "2% von Grundmana\nSofort 30 sek. Abklingzeit\n1 Aufladung\nFügt Gegnern innerhalb von 12 Metern um Euch (5.149% der Zaubermacht) Frostschaden zu und friert sie 6 Sek. lang fest. Schaden kann den Bewegungsunfähigkeitseffekt unterbrechen." }
entries[126] = { ["name"] = "Auge von Kilrogg", ["text"] = "3% von Grundmana Unbegrenzte Reichweite\nWirken in 2 sek.\nBeschwört ein Auge von Kilrogg und bindet Eure Sicht daran. Das Auge ist getarnt und bewegt sich schnell, ist sehr sehr verwundbar." }
entries[130] = { ["name"] = "Langsamer Fall", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nVerringert 30 Sek. lang die Fallgeschwindigkeit eines Gruppenmitglieds." }
entries[133] = { ["name"] = "Feuerball", ["text"] = "1% von Grundmana 40 Meter Reichweite\nWirken in 2.25 sek.\nWirft eine feurige Kugel, die (154.8% der Zaubermacht) Feuerschaden verursacht." }
entries[134] = { ["name"] = "Feuerschild", ["text"] = "30 Meter Reichweite\nWirken in 1 sek. 15 sek. Abklingzeit\nUmgibt einen Verbündeten mit einem Flammenschild, der alle 3 Sek. in der Nähe befindlichen Feinden 1 Feuerschaden zufügt. Hält 1 Min. lang an." }
entries[136] = { ["name"] = "Tier heilen", ["text"] = "45 Meter Reichweite\nSofort 10 sek. Abklingzeit\nHeilt Euren Begleiter im Verlauf von 10 Sek. um 50% seiner gesamten Gesundheit. [ Medizin der Wildnis : Pro Tick besteht eine Chance von 25%, einen schädlichen Magieeffekt von Eurem Begleiter zu entfernen ]" }
entries[139] = { ["name"] = "Erneuerung", ["text"] = "8% von Grundmana 40 Meter Reichweite\nSofort\nErfüllt das Ziel mit Glauben an das Licht, wodurch es im Verlauf von 15 Sek. um (160% der Zaubermacht) Gesundheit geheilt wird." }
entries[172] = { ["name"] = "Verderbnis", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nVerderbt das Ziel, verursacht (17.25% der Zaubermacht) Schattenschaden sowie im Verlauf von 14 Sek. (113.75% der Zaubermacht) zusätzlichen Schattenschaden." }
