entries[246] = { ["name"] = "Verlangsamen", ["text"] = "140 Mana 30 Meter Reichweite\nSofort\nVerlangsamt 6 Sek. lang die Bewegung des Feindes um 35% und sein Angriffstempo um 35%." }
