entries[339] = { ["name"] = "Wucherwurzeln", ["text"] = "1.2% von Grundmana 35 Meter Reichweite\nWirken in 1.7 sek.\nHält das Ziel 30 Sek. lang an Ort und Stelle fest. Schaden kann den Effekt unterbrechen. [ Inkarnation: Baum des Lebens : Baum des Lebens: Spontanzauber ]" }
entries[348] = { ["name"] = "Feuerbrand", ["text"] = "1.5% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nVerbrennt den Gegner und fügt ihm sofort (81.3483% der Zaubermacht) Feuerschaden sowie im Verlauf von 18 Sek. zusätzlich (305.056% der Zaubermacht) Feuerschaden zu.\n\nRegelmäßiger Schaden erzeugt ein Seelensplitterfragment und hat eine Chance von 50%, bei kritischen Treffern ein zusätzliches zu erzeugen." }
entries[355] = { ["name"] = "Spott", ["text"] = "30 Meter Reichweite\nSofort 8 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift." }
entries[370] = { ["name"] = "Reinigen", ["text"] = "14% von Grundmana 30 Meter Reichweite\nSofort\nReinigt das gegnerische Ziel und entzieht 1 nützlichen magischen Effekt.\n[Ist 'Reinigen' erfolgreich, wird Euch eine Aufladung von 'Waffe des Mahlstroms' gewährt.]" }
entries[379] = { ["name"] = "Erdschild", ["text"] = "300 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild, der Eure bei diesem Ziel hervorgerufene Heilung um 20% erhöht und es bei erlittenem Schaden um [(73% der Zaubermacht) * 1.2] Gesundheit heilt. Diese Heilung kann nur einmal alle 3 Sek. auftreten. Maximal 9 Aufladungen .\n\n[ Elementare Umkreisung : 'Erdschild' kann immer nur auf den Schamanen und ein weiteres Ziel gleichzeitig angewendet werden. Es können bis zu zwei Elementarschilde auf dem Schamanen aktiv sein / 'Erdschild' kann immer nur auf ein Ziel gleichzeitig angewendet werden. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.]" }
entries[408] = { ["name"] = "Nierenhieb", ["text"] = "25 Energie / 1 zu 5 Combopunkte Nahkampfreichweite\nSofort 30 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nFinishing-Move, der das Ziel betäubt . Hält pro Combopunkt länger an, bis zu maximal 8 Sek.:\n1 Punkt: 4 Sek.\n2 Punkte: 5 Sek.\n3 Punkte: 6 Sek.\n4 Punkte: 7 Sek.\n5 Punkte: 8 Sek." }
