entries[458] = { ["name"] = "Braunes Pferd", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares braunes Pferd oder gibt es wieder frei.\n\"Dank seiner Geduld und Ausdauer ein Favorit bei den Wachen von Sturmwind.\"\nVerkäufer:\nUnger Stattfort\nZone:\nSumpfland\nKosten:\n1" }
