entries[465] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort\nGruppen- und Schlachtzugsmitglieder innerhalb von 40 Metern werden durch ihre Hingabe gestärkt, wodurch sich ihr erlittener Schaden um 3% verringert." }
entries[467] = { ["name"] = "Dornen" }
entries[468] = { ["name"] = "Schimmel", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Schimmel oder gibt ihn wieder frei.\n\"Der mächtige und unbeugsame Schimmel kommt oft in den Mythen der alten Menschenstämme vor.\"\nKlassisch" }
entries[470] = { ["name"] = "Rappe", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Rappen oder gibt ihn wieder frei.\n\"Wird angeblich wegen seines dunklen Fells von der SI:7 bei Nachtmissionen bevorzugt.\"\nVerkäufer:\nKatie Stokx\nZone:\nSturmwind\nKosten:\n1" }
entries[471] = { ["name"] = "Palomino", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Palomino oder gibt es wieder frei." }
entries[472] = { ["name"] = "Schecke", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares geschecktes Pferd oder gibt es wieder frei.\n\"Aufgrund seines ruhigen Temperaments eignet er sich hervorragend, um junge Kinder ans Reiten zu gewöhnen.\"\nVerkäufer:\nKatie Stokx\nZone:\nSturmwind\nKosten:\n1" }
entries[475] = { ["name"] = "Fluch aufheben", ["text"] = "1.3% von Grundmana 40 Meter Reichweite\nSofort 8 sek. Abklingzeit\nBefreit ein befreundetes Ziel von allen Flüchen." }
