entries[512] = { ["name"] = "Eisketten", ["text"] = "35 Mana 30 Meter Reichweite\nWirken in 1.3 sek.\nSchlingt eisige Ketten um das Ziel, die es 5 Sek. lang am Platz festhalten." }
entries[518] = { ["name"] = "Wurm beschwören", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört eine Ausgeburt von Fankriss aus den Tiefen von Ahn'Qiraj." }
entries[527] = { ["name"] = "Läutern", ["text"] = "1.3% von Grundmana 40 Meter Reichweite\nSofort 8 sek. Abklingzeit\n1 Aufladung\nBannt auf das Ziel wirkende schädliche Effekte. Entfernt sämtliche Magie [ Verbessertes Läutern : - und Krankheits ]effekte." }
entries[528] = { ["name"] = "Magiebannung", ["text"] = "14% von Grundmana 30 Meter Reichweite\nSofort\nEntfernt 1 nützlichen magischen Stärkungszauber von einem gegnerischen Ziel." }
entries[530] = { ["name"] = "Bezauberung (Besitz ergreifen)" }
entries[546] = { ["name"] = "Wasserwandeln", ["text"] = "30 Meter Reichweite\nSofort\nErmöglicht dem verbündeten Ziel, 10 Min. lang auf Wasser zu wandeln. Schaden bricht den Effekt ab." }
entries[550] = { ["name"] = "Gift neutralisieren", ["text"] = "100 Mana 30 Meter Reichweite\nSofort\nDas Ziel ist 30 Sek. lang gegen Gift immun und wird von allen bereits vorhandenen Giften geheilt." }
entries[556] = { ["name"] = "Astraler Rückruf", ["text"] = "Wirken in 10 sek. 10 min Abklingzeit\nReißt Euch durch den Wirbelnden Nether zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern." }
entries[568] = { ["name"] = "Arkane Wucht", ["text"] = "Sofort\nFügt allen Gegnern innerhalb von 10 Metern 2958 Arkanschaden zu, verringert ihre Bewegungsgeschwindigkeit um 70% und stößt sie zurück." }
entries[578] = { ["name"] = "Schwarzer Wolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schwarzen Wolf oder gibt ihn wieder frei.\n\"Heult laut genug, um meilenweit gehört zu werden.\"\nVerkäufer:\nOgunaro Wolfsläufer\nZone:\nOrgrimmar\nKosten:\n1" }
entries[579] = { ["name"] = "Roter Wolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren roten Wolf oder gibt ihn wieder frei.\n\"Es verbleiben nur noch wenige in ganz Azeroth, und nur die Erfahrensten von uns haben sie je zu Gesicht bekommen.\"\nKlassisch" }
entries[580] = { ["name"] = "Waldwolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Waldwolf oder gibt ihn wieder frei.\n\"Heult laut genug, um meilenweit gehört zu werden.\"\nVerkäufer:\nOgunaro Wolfsläufer\nZone:\nOrgrimmar\nKosten:\n1" }
entries[581] = { ["name"] = "Winterwolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Winterwolf oder gibt ihn wieder frei.\n\"Uralte Legenden der Furbolgs nach waren Wölfe mit weißem Fell durch die zwei Monde von Azeroth gesegnet.\"\nKlassisch" }
entries[585] = { ["name"] = "Heilige Pein", ["text"] = "3% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nPeinigt einen Gegner mit (70.5% der Zaubermacht) Heiligschaden [ Refugium : und absorbiert die nächsten [(Schattenzaubermacht * 100 / 100) * (1 + Vielseitigkeit)] Schaden, die von diesem Gegner verursacht werden ] [ Heiliges Feuer : Außerdem besteht eine Chance von 20%, die Abklingzeit von 'Heiliges Feuer' abzuschließen ]." }
entries[586] = { ["name"] = "Verblassen", ["text"] = "Sofort 30 sek. Abklingzeit\nLässt Euch verblassen und entfernt Eure gesamte Bedrohung. Verringert zusätzlich die Entfernung, aus der Gegner Euch angreifen. Hält 10 Sek. lang an." }
entries[589] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "2% von Grundmana 40 Meter Reichweite\nSofort\nDisziplin, Heilig\nEin Wort der Dunkelheit, das sofort (12.92% der Zaubermacht) Schattenschaden sowie im Verlauf von 16 Sek. zusätzlich (76.704% der Zaubermacht) Schattenschaden verursacht.\n\nSchatten\nEin Wort der Dunkelheit, das sofort (12.92% der Zaubermacht) Schattenschaden sowie im Verlauf von 16 Sek. zusätzlich (76.704% der Zaubermacht) Schattenschaden verursacht.\n\nErzeugt 3 Wahnsinn." }
entries[596] = { ["name"] = "Gebet der Heilung", ["text"] = "4.75% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nEin mächtiges Gebet, das Euer Ziel und 4 verletzte Verbündete innerhalb von 40 Metern um (320.953% der Zaubermacht) Gesundheit heilt." }
entries[603] = { ["name"] = "Verdammnis", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBelegt das Ziel mit drohender Verdammnis, was sofort (104.406% der Zaubermacht) Schattenschaden verursacht und nach 20 Sek. Gegnern innerhalb von 10 Metern (290.928% der Zaubermacht) Schattenschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nDas verzehren eines 'Dämonischen Kerns' verringert die Dauer von 'Verdammnis' um 3 Sek." }
entries[605] = { ["name"] = "Gedankenkontrolle", ["text"] = "2% von Grundmana 30 Meter Reichweite\nWirken in 1.8 sek." }
entries[606] = { ["name"] = "Gedankenverfall", ["text"] = "240 Mana 30 Meter Reichweite\nWirken in 2 sek.\nEntzieht dem Ziel 30 Sek. lang insgesamt 34 Mana." }
entries[633] = { ["name"] = "Handauflegung", ["text"] = "40 Meter Reichweite\nSofort 10 min Abklingzeit\nHeilt ein verbündetes Ziel um einen Betrag, der 100% Eurer maximalen Gesundheit entspricht.\n\nKann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 30 Sek. lang anhält." }
entries[642] = { ["name"] = "Gottesschild", ["text"] = "Sofort 5 min Abklingzeit\nGewährt 8 Sek. lang Immunität vor jeglichem Schaden, schädlichen Effekten, Rückstößen und erzwungenen Bewegungseffekten.\n\nKann nicht eingesetzt werden, wenn 'Vorahnung' auf Euch wirkt. Ruft den Effekt 'Vorahnung' hervor, der 30 Sek. lang anhält." }
