entries[673] = { ["name"] = "Schwache Verteidigung", ["text"] = "Sofort\nErhöht Eure Rüstung 1 Stunde lang um 0 . Wächterelixier." }
entries[674] = { ["name"] = "Beidhändigkeit", ["text"] = "Ermöglicht die Verwendung von Einhandwaffen und Schildhandwaffen in der Schildhand." }
entries[686] = { ["name"] = "Schattenblitz", ["text"] = "1.5% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Schattenblitz auf den Gegner und verursacht (70.2% der Zaubermacht) Schattenschaden. [ Dämonologie : Erzeugt 1 Seelensplitter. ]" }
entries[688] = { ["name"] = "Wichtel beschwören", ["text"] = "1 Seelensplitter\nWirken in 6 sek.\nBeschwört einen Wichtel, der unter Eurem Befehl steht und Feuerblitze verschießt." }
entries[691] = { ["name"] = "Teufelsjäger beschwören", ["text"] = "1 Seelensplitter\nWirken in 6 sek.\nBeschwört einen Teufelsjäger, der unter Eurem Befehl steht und das Zauberwirken von Gegnern unterbrechen kann." }
entries[697] = { ["name"] = "Leerwandler beschwören", ["text"] = "1 Seelensplitter\nWirken in 6 sek.\nBeschwört einen Leerwandler, der unter Eurem Befehl steht und schwerem Schaden widerstehen kann." }
entries[698] = { ["name"] = "Ritual der Beschwörung", ["text"] = "5% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 2 min) 2 min Abklingzeit\nBeginnt mit einem Ritual zur Erschaffung eines Beschwörungsportals, das vom Zaubernden und 2 Verbündeten abgeschlossen werden muss. Mithilfe des Portals können Gruppen- und Schlachtzugsmitglieder herbeigerufen werden." }
entries[700] = { ["name"] = "Schlaf", ["text"] = "60 Mana 30 Meter Reichweite\nWirken in 1.5 sek." }
entries[702] = { ["name"] = "Fluch der Schwäche", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nErhöht die Zeit zwischen Angriffen eines Gegners 2 Min. lang um 20%.\n\nFlüche: Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[703] = { ["name"] = "Erdrosseln", ["text"] = "45 Energie Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Einhändige Nahkampfwaffe\nErdrosselt den Gegner und fügt ihm im Verlauf von 18 Sek. (351.9% der Angriffskraft) Blutungsschaden zu.\n\nGewährt 1 Combopunkt." }
entries[710] = { ["name"] = "Verbannen", ["text"] = "1.5% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nVerbannt einen gegnerischen Dämon, eine Entartung [ Großes Verbannen : einen Untoten ] oder einen Elementar und macht das Ziel 30 Sek. lang handlungsunfähig. Maximal 1 Ziel. Wenn Ihr erneut 'Verbannen' auf das Ziel wirkt, wird der Effekt aufgehoben." }
entries[712] = { ["name"] = "Sukkubus beschwören", ["text"] = "1 Seelensplitter\nWirken in 6 sek.\nBeschwört einen Sukkubus, der unter Eurem Befehl steht und gegnerische Humanoide verführt, die dadurch nicht angreifen können." }
entries[720] = { ["name"] = "Umschlingen", ["text"] = "Sofort\nDie Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig." }
entries[731] = { ["name"] = "Umschlingen", ["text"] = "Sofort\nDie Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig." }
entries[740] = { ["name"] = "Gelassenheit", ["text"] = "3.68% von GrundmanaKanalisiert (Wirken in 5 sek.) 3 min Abklingzeit\nHeilt alle Verbündeten innerhalb von 40 Metern im Verlauf von 5 Sek. um [5 * (542.8% der Zaubermacht)] Gesundheit. Jede Heilung heilt das Ziel zusätzlich im Verlauf von 8 Sek. um (23.736% der Zaubermacht) Gesundheit. Dieser Effekt ist stapelbar.\n\nHeilung bei Zielen über 5 Ziele hinaus verringert." }
entries[742] = { ["name"] = "Pulverisieren", ["text"] = "10 min Abklingzeit\n(Procchance: 35%)" }
entries[744] = { ["name"] = "Gift", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Gegner 15 Sek. lang alle 3 Sek. Naturschaden zu." }
entries[745] = { ["name"] = "Gespinst", ["text"] = "30 Meter Reichweite\nSofort\nZaubert ein Netz über einen Feind und macht ihn so 3 Sek. lang bewegungsunfähig." }
entries[746] = { ["name"] = "Erste Hilfe", ["text"] = "15 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nHeilt im Verlauf von 6 Sek. 50 Schaden." }
entries[747] = { ["name"] = "Abbilder beschwören", ["text"] = "Sofort\nBeschwört 2 Kopien des Zaubernden." }
entries[750] = { ["name"] = "Plattenpanzer", ["text"] = "Gestattet Euch, Gegenstände der Kategorie 'Plattenrüstung' anzulegen." }
entries[755] = { ["name"] = "Lebenslinie", ["text"] = "45 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nOpfert im Verlauf von 5 Sek. 25% Eurer maximalen Gesundheit, um Euren beschworenen Dämon um das Doppelte dieses Werts zu heilen." }
entries[759] = { ["name"] = "Manaedelstein herbeizaubern", ["text"] = "18% von Grundmana\nWirken in 3 sek.\nZaubert einen Manaedelstein herbei, der zum sofortigen Wiederherstellen von 25% Mana verwendet werden kann und 12 Sek. lang 5% Zauberschaden gewährt. Enthält bis zu 3 Aufladungen.\n\nHerbeigezauberte Gegenstände\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Min. ausloggt." }
entries[768] = { ["name"] = "Katzengestalt", ["text"] = "Sofort\nVerwandelt Eure Gestalt in die einer Katze, erhöht den Schaden automatischer Angriffe um 40% sowie die Bewegungsgeschwindigkeit um 30%, schützt Euch vor Verwandlungseffekten und verringert den erlittenen Fallschaden.\n\nDer Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten." }
entries[772] = { ["name"] = "Verwunden", ["text"] = "20 Wut Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerwundet das Ziel und fügt ihm sofort (124.581% der Angriffskraft) körperlichen Schaden sowie zusätzlich im Verlauf von 15 Sek. (190.465% der Angriffskraft) Blutungsschaden zu. [ Donnerknall : 'Donnerknall' belegt 5 Ziele in der Nähe mit 'Verwunden'. ]" }
entries[774] = { ["name"] = "Verjüngung", ["text"] = "5% von Grundmana 40 Meter Reichweite\nSofort\nHeilt das Ziel im Verlauf von 12 Sek. um (103.52% der Zaubermacht) Gesundheit. [ Verschmelzung : Ihr könnt 'Verjüngung' zweimal auf dasselbe Ziel anwenden ] [ Inkarnation: Baum des Lebens : Baum des Lebens: Heilung um 40% erhöht und Manakosten um 30% verringert. ]" }
entries[781] = { ["name"] = "Rückzug", ["text"] = "Unbegrenzte Reichweite\nSofort 20 sek. Abklingzeit\n1 Aufladung\nSpringt rückwärts. [ Impromptu : Dabei befreit Ihr Euch von bewegungseinschränkenden Effekten und erhöht Eure Bewegungsgeschwindigkeit 4 Sek. lang um 0% ] [ Um ein Haar : Außerdem aktiviert Ihr eine Netzfalle, die alle gegnerischen Ziele innerhalb von 8 Metern mit klebrigen Netzen bedeckt, die sie 8 Sek. lang bewegungsunfähig machen ]" }
entries[783] = { ["name"] = "Reisegestalt", ["text"] = "Sofort\nVerwandelt Euch in eine an Eure aktuelle Umgebung angepasste Reisegestalt und erhöht Eure Bewegungsgeschwindigkeit auf Land, im Wasser oder in der Luft. Schützt Euch vor Verwandlungseffekten.\n\nDer Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten." }
entries[785] = { ["name"] = "Wahre Erfüllung", ["text"] = "260 Mana 45 Meter Reichweite\nWirken in 0.5 sek.\nVon den Kräften des Propheten Skeram bekehrt, wird das Ziel mit heiliger Macht erfüllt. Die Zauber des Ziels werden sofort gewirkt, der verursachte Schaden ist um 300%, alle Widerstände sind um 269 und die Bewegungsgeschwindigkeit ist um 40% erhöht. Hält 20 Sek. lang an." }
