entries[845] = { ["name"] = "Spalten", ["text"] = "20 Wut Nahkampfreichweite\nSofort 4.5 sek. Abklingzeit\nGreift alle Gegner vor Euch an, fügt ihnen (217.745% der Angriffskraft) körperlichen Schaden zu und belegt sie mit 'Tiefe Wunden'. 'Spalten' verbraucht Euren Effekt 'Überwältigen', um mehr Schaden zu verursachen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[851] = { ["name"] = "Verwandlung: Schaf", ["text"] = "200 Mana 20 Meter Reichweite\nSofort\nVerwandelt den Feind bis zu 10 Sek. lang in ein hilfloses Schaf, das weder Zauber wirken noch angreifen kann und sich um 60% langsamer bewegt." }
