entries[921] = { ["name"] = "Taschendiebstahl", ["text"] = "10 Meter Reichweite\nSofort 0.5 sek. Abklingzeit\nBenötigt Verstohlenheit\nBegeht einen Taschendiebstahl am Ziel." }
