entries[974] = { ["name"] = "Erdschild", ["text"] = "5% von Grundmana 40 Meter Reichweite\nSofort Erfordert Level 30 (Elementar, Verstärkung)\nSchützt das Ziel mit einem Erdschild, der Eure bei diesem Ziel hervorgerufene Heilung um 20% erhöht und es bei erlittenem Schaden um [(73% der Zaubermacht) * (1.2)] Gesundheit heilt. Diese Heilung kann nur einmal alle 3 Sek. auftreten. Maximal 9 Aufladungen .\n\n[ Elementare Umkreisung : 'Erdschild' kann immer nur auf den Schamanen und ein weiteres Ziel gleichzeitig angewendet werden. Es können bis zu zwei Elementarschilde auf dem Schamanen aktiv sein / 'Erdschild' kann immer nur auf ein Ziel gleichzeitig angewendet werden. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.](3s Abklingzeit)" }
entries[980] = { ["name"] = "Agonie", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nFügt dem Ziel immer stärkere Schmerzen zu, die im Verlauf von 18 Sek. [(3.01508% der Zaubermacht) * 18 / 2 * 6] Schattenschaden verursachen. Zunächst wird nur geringer Schaden verursacht, der sich aber mit zunehmender Dauer erhöht. Durch die Auffrischung des Zaubers wird die aktuelle Schadensstufe beibehalten.\n\nWenn 'Agonie' Schaden verursacht, wird manchmal 1 Seelensplitter erzeugt." }
entries[982] = { ["name"] = "Tier wiederbeleben", ["text"] = "35 Fokus\nWirken in 2.5 sek.\nBringt Euer totes Tier mit 100% seiner Grundgesundheit wieder ins Leben zurück." }
entries[1022] = { ["name"] = "Segen des Schutzes", ["text"] = "3% von Grundmana 40 Meter Reichweite\nSofort 5 min Abklingzeit\n1 Aufladung\nHeilig, Vergeltung\nSegnet ein Gruppen- oder Schlachtzugsmitglied und gewährt ihm 10 Sek. lang Immunität gegen körperlichen Schaden und schädliche Effekte.\n\nKann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 30 Sek. lang anhält.\n\nSchutz\nSegnet ein Gruppen- oder Schlachtzugsmitglied und gewährt ihm 10 Sek. lang Immunität gegen körperlichen Schaden und schädliche Effekte.\n\nKann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 30 Sek. lang anhält.\n\nTeilt sich eine Abklingzeit mit 'Segen des Zauberschutzes'." }
entries[1044] = { ["name"] = "Segen der Freiheit", ["text"] = "1.4% von Grundmana 40 Meter Reichweite\nSofort 25 sek. Abklingzeit\n1 Aufladung\nSegnet ein Gruppen- oder Schlachtzugsmitglied und gewährt ihm Immunität gegen bewegungseinschränkende Effekte. [ Absolute Freiheit : Zusätzlich erhöht der Segen seine Bewegungsgeschwindigkeit um 30% ]Hält 8 Sek. lang an." }
entries[1050] = { ["name"] = "Opferung", ["text"] = "Wirken in 1 sek." }
entries[1064] = { ["name"] = "Kettenheilung", ["text"] = "15% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt das verbündete Ziel um (231% der Zaubermacht) Gesundheit und springt dann bis zu 15 Meter auf die 3 am schwersten verletzten Verbündeten in der Nähe über, um sie zu heilen. Mit jedem Sprung verringert sich die Heilung um 30%." }
entries[1066] = { ["name"] = "Reisegestalt", ["text"] = "Sofort\nVerwandelt Euch in eine Wassergestalt. Die Schwimmgeschwindigkeit wird um 100% erhöht und Ihr könnt unter Wasser atmen. Beschützt Euch außerdem vor Verwandlungseffekten.\n\nDer Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten." }
entries[1079] = { ["name"] = "Zerfetzen", ["text"] = "20 Energie / 1 zu 5 Combopunkte Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der regelmäßigen Blutungsschaden verursacht. Hält pro Combopunkt länger an.\n\n1 Punkt: [(64.44% der Angriffskraft) * 2] im Verlauf von 8 Sek.\n2 Punkte: [(64.44% der Angriffskraft) * 3] im Verlauf von 12 Sek.\n3 Punkte: [(64.44% der Angriffskraft) * 4] im Verlauf von 16 Sek.\n4 Punkte: [(64.44% der Angriffskraft) * 5] im Verlauf von 20 Sek.\n5 Punkte: [(64.44% der Angriffskraft) * 6] im Verlauf von 24 Sek." }
