entries[1122] = { ["name"] = "Höllenbestie beschwören", ["text"] = "2% von Grundmana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nBeschwört eine Höllenbestie aus dem Wirbelnden Nether, die beim Einschlag (60% der Zaubermacht) Feuerschaden verursacht und alle Gegner im Effektbereich für 2 Sek. betäubt.\n\nDie Höllenbestie steht 30 Sek. lang unter Eurem Befehl, fügt allen Gegnern in der Nähe alle 2 Sek. [(55% der Zaubermacht) * (111) / 100] Schaden zu und erzeugt alle 1 Sek. 1 Seelensplitterfragment." }
entries[1126] = { ["name"] = "Mal der Wildnis", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nErfüllt ein verbündetes Ziel mit der Macht der Wildnis. Erhöht die Vielseitigkeit des Ziels 60 Min. lang um 3%.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt." }
