entries[1130] = { ["name"] = "Mal des Jägers", ["text"] = "100 Meter Reichweite\nSofort\nBelegt das Ziel mit dem Mal des Jägers, das den Distanzschaden aller Angreifer gegen dieses Ziel um 0% erhöht. Das Ziel kann immer vom Jäger gesehen und aufgespürt werden.\n\nDie Fähigkeiten 'Arkaner Schuss', 'Schimärenschuss', 'Tötungsbefehl' und 'Explosivschuss' rufen automatisch den Effekt von 'Mal des Jägers' hervor.\n\nHält 5 Min. lang an." }
