entries[1234] = { ["name"] = "Joe's God Mode", ["text"] = "Unbegrenzte Reichweite\nSofort 0.5 sek. Abklingzeit\nTödlicher Schaden wird absorbiert.\nHeilt alle 1 Sek. 100% Gesundheit." }
entries[1329] = { ["name"] = "Verstümmeln", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nGreift mit beiden Waffen an und verursacht insgesamt [(115% der Angriffskraft) + (115% der Angriffskraft) * 0.5] körperlichen Schaden.\n\nGewährt 2 Combopunkte." }
entries[1330] = { ["name"] = "Erdrosseln - Stille", ["text"] = "Unbegrenzte Reichweite\nSofort\nBringt das Ziel 5 Sek. lang zum Schweigen." }
entries[1364] = { ["name"] = "Unerschütterlicher Wille" }
entries[1373] = { ["name"] = "'Teufelsjäger beschwören' lehren" }
entries[1386] = { ["name"] = "Echos von Lordaeron" }
entries[1446] = { ["name"] = "Wassergestalt" }
entries[1449] = { ["name"] = "Arkane Explosion", ["text"] = "10% von Grundmana\nSofort\nVerursacht eine magische Explosion um den Zaubernden herum, die allen Gegnern innerhalb von 10 Metern (77.2% der Zaubermacht) Arkanschaden zufügt. [ Arkan (Level 10) : Erzeugt 1 Arkane Aufladung, wenn Ziele getroffen werden. ]" }
entries[1454] = { ["name"] = "Aderlass", ["text"] = "Sofort 30 sek. Wiederaufladung\n3 Aufladungen\nGewährt Euch auf Kosten von 10% Eurer maximalen Gesundheit 1 Seelensplitter." }
entries[1459] = { ["name"] = "Arkane Intelligenz", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nErfüllt das Ziel mit Brillanz, die seine Intelligenz 1 Stunde lang um 3% erhöht.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten." }
entries[1462] = { ["name"] = "Wildtierkunde", ["text"] = "40 Meter Reichweite\nSofort\nSammelt Informationen über das Zielwildtier. Zeigt Ernährung, Fähigkeiten, Spezialisierung sowie Zähmbarkeit an und ob es exotisch ist." }
entries[1463] = { ["name"] = "Fluss des Beschwörers", ["text"] = "Im Kampf durchfließt Euch magische Energie, die anwächst, bis eine Schadenserhöhung von 10% erreicht ist, und dann abnimmt, bis die Schadenserhöhung 2% beträgt. Dieser Zyklus wiederholt sich alle 10 Sek." }
entries[1464] = { ["name"] = "Zerschmettern", ["text"] = "20 Wut Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nZerschmettert einen Gegner und fügt ihm (116.725% der Angriffskraft) körperlichen Schaden zu. [ Sturm der Schwerter : Erzeugt 10 Wut. ]" }
entries[1485] = { ["name"] = "Rollender Brocken", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nFeuert mit einer Distanzwaffe auf das Ziel." }
entries[1490] = { ["name"] = "Chaosbrandmal", ["text"] = "100 Meter Reichweite\nSofort\nEuer Schaden fügt dem Ziel ein Brandmal zu, das dessen erlittenen Magieschaden um 3% erhöht." }
entries[1494] = { ["name"] = "Wildtiere aufspüren", ["text"] = "Sofort\nZeigt alle Wildtiere in der Nähe auf der Minikarte an." }
entries[1513] = { ["name"] = "Wildtier ängstigen", ["text"] = "25 Fokus 30 Meter Reichweite\nWirken in 1.5 sek.\nJagt einem Wildtier Angst ein, woraufhin es bis zu 20 Sek. lang verängstigt wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils einem Wildtier Angst eingejagt werden." }
entries[1515] = { ["name"] = "Wildtier zähmen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nZähmt ein Wildtier, sodass es zu Eurem Begleiter wird. Wenn Ihr aus irgendeinem Grund die Aufmerksamkeit des Tieres verliert, schlägt die Zähmung fehl.\n\nIhr müsst Euren aktiven Begleiter freigeben und einen freien Platz im Menü 'Begleiter rufen' haben, bevor ein neues Wildtier gezähmt werden kann. Exotische Tiere können nur von Jägern mit Tierherrschaftsspezialisierung gezähmt werden." }
entries[1516] = { ["name"] = "Schnellschuss", ["text"] = "5 - 30 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\nInflicts Physical damage to an enemy." }
entries[1528] = { ["name"] = "Meister befreien", ["text"] = "5 Meter Reichweite\nSofort\nBefreit Euren Meister von allen Fesseln." }
entries[1536] = { ["name"] = "Langschuss II" }
entries[1538] = { ["name"] = "Laden", ["text"] = "20 Meter Reichweite\nWirken in 5 sek.\nLädt die Rute von Helcular auf, wenn sie an drei zeremoniellen Scheiterhaufen benutzt wird." }
entries[1539] = { ["name"] = "Tier füttern", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerfüttert Eurem Tier die ausgewählte Speise, wodurch es 50% seiner gesamten Gesundheit regeneriert. Kann nicht im Kampf angewandt werden." }
entries[1543] = { ["name"] = "Leuchtfeuer", ["text"] = "40 Meter Reichweite\nSofort 20 sek. Abklingzeit\nDeckt 20 Sek. lang alle versteckten und unsichtbaren Gegner innerhalb des Zielbereichs auf." }
entries[1557] = { ["name"] = "Volles Tempo", ["text"] = "Sofort\nErhöht Bewegungsgeschwindigkeit um 300." }
entries[1588] = { ["name"] = "Tier-Ausbau" }
entries[1604] = { ["name"] = "Benommen", ["text"] = "Nahkampfreichweite\nSofort\nEin erschütternder Schlag, der das Ziel zum Absitzen zwingt und die Bewegungsgeschwindigkeit 4 Sek. lang um 50% verringert." }
entries[1609] = { ["name"] = "Kreissäge des Aschenbringers" }
entries[1645] = { ["name"] = "Worgenform", ["text"] = "Nahkampfreichweite\nSofort\nLehrt die duale Worgenform" }
entries[1650] = { ["name"] = "Verlangsamender Stoß III" }
entries[1680] = { ["name"] = "Wirbelwind", ["text"] = "20 Wut 100 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nEntfesselt einen Wirbel aus Stahl, der [ Schlachteifer : Euer Primärziel mit 'Zerschmettern' trifft und ] allen Zielen in der Nähe [3 * (62.996% der Angriffskraft)] körperlichen Schaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[1706] = { ["name"] = "Levitieren", ["text"] = "0.9% von Grundmana 30 Meter Reichweite\nSofort\nLässt ein Gruppen- oder Schlachtzugsmitglied 10 Min. lang ein Stückchen über dem Boden schweben, sorgt für einen sanften Fall und ermöglicht ihm das Wandeln über Wasser." }
entries[1714] = { ["name"] = "Fluch der Sprachen", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nZwingt das Ziel, Dämonisch zu sprechen, wodurch die Zauberzeit aller Zauber für 1 Min. um 30% erhöht wird.\n\nFlüche: Ein Hexenmeister kann auf jedem Ziel nur einen Fluch aktiv haben." }
entries[1715] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFügt dem Gegner (15% der Angriffskraft) körperlichen Schaden zu und verstümmelt ihn, wodurch seine Bewegungsgeschwindigkeit 15 Sek. lang um 50% verringert wird." }
entries[1719] = { ["name"] = "Tollkühnheit", ["text"] = "Sofort 1.5 min Abklingzeit\nLässt Euch zum Berserker werden und erhöht 12 Sek. lang die Wuterzeugung um 100% sowie die kritische Trefferchance Eurer Fähigkeiten um 20%.\n\nFuror\nGenerates 0 Rage." }
entries[1725] = { ["name"] = "Ablenken", ["text"] = "30 Energie 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBewirkt eine Ablenkung, die die Aufmerksamkeit aller Ziele in der Nähe 10 Sek. lang auf sich zieht. Kann im Verstohlenheitsmodus eingesetzt werden." }
entries[1752] = { ["name"] = "Finsterer Stoß", ["text"] = "45 Energie Nahkampfreichweite\nSofort\nBenötigt Einhändige Nahkampfwaffe\nVersetzt einem Gegner einen brutalen Schlag, der (21.762% der Angriffskraft) körperlichen Schaden verursacht.\n\nGewährt 1 Combopunkt." }
entries[1766] = { ["name"] = "Tritt", ["text"] = "Nahkampfreichweite\nSofort 15 sek. Abklingzeit\nEin schneller Tritt, der das Wirken von Zaubern unterbricht und 3 Sek. lang verhindert, dass diese Art Zauber gewirkt werden kann." }
entries[1776] = { ["name"] = "Solarplexus", ["text"] = "25 Energie Nahkampfreichweite\nSofort 25 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nMacht einen Gegner für 4 Sek. handlungsunfähig. Schaden kann den Effekt unterbrechen.\n\nIhr müsst vor Eurem Ziel stehen.\n\nGewährt 1 Combopunkte." }
entries[1784] = { ["name"] = "Verstohlenheit", ["text"] = "Sofort 2 sek. Abklingzeit\nVerbirgt Euch bis Abbruch in den Schatten, wodurch Ihr um Gegner herumschleichen könnt, ohne gesehen zu werden. [ Nachtpirscher : Die Bewegungsgeschwindigkeit im Verstohlenheitsmodus ist um 0% und der verursachte Schaden um 0% erhöht ] [ Schattenfokus : Im Verstohlenheitsmodus sind die Fähigkeitskosten um 5% verringert ] [ Meister des hinterhältigen Angriffs : Angriffe aus dem Verstohlenheitsmodus heraus und für 5 Sek. danach verursachen 10% mehr Schaden ]" }
entries[1800] = { ["name"] = "Entmutigender Schlag II" }
entries[1804] = { ["name"] = "Schloss knacken", ["text"] = "5 Meter Reichweite\nWirken in 1.5 sek.\nErmöglicht das Öffnen verschlossener Truhen und Türen, die eine Fertigkeit von bis zu 80 benötigen." }
entries[1809] = { ["name"] = "Schlossknacken" }
entries[1810] = { ["name"] = "Schlossknacken" }
entries[1822] = { ["name"] = "Krallenhieb", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nAttackiert das Ziel mit Krallen und fügt ihm so (32.34% der Angriffskraft) Blutungsschaden sowie im Verlauf von 15 Sek. zusätzlich (163.35% der Angriffskraft) Blutungsschaden zu. [ Infizierte Wunden : Verringert die Bewegungsgeschwindigkeit des Ziels für 12 Sek. um 20% ]\nGewährt 1 Combopunkt." }
entries[1833] = { ["name"] = "Fieser Trick", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nBenötigt Verstohlenheit\nBetäubt das Ziel für 6 Sek.\n\nGewährt 1 Combopunkt." }
entries[1834] = { ["name"] = "Sammelt Tempo an", ["text"] = "Sofort\nErhöht Bewegungsgeschwindigkeit." }
entries[1843] = { ["name"] = "Entschärfen", ["text"] = "5 Meter Reichweite\nWirken in 2 sek.\nEntschärft die Falle..." }
entries[1844] = { ["name"] = "Entwaffnender Zorn", ["text"] = "Sofort\nWenn 'Entwaffnen' aktiv ist, während dieser Effekt wirkt, wird Attumen einen neuen Satz Kräfte auswählen." }
entries[1848] = { ["name"] = "Rutengangbeschwörungsgesang" }
entries[1850] = { ["name"] = "Spurt", ["text"] = "Sofort 2 min Abklingzeit\nVerwandelt Eure Gestalt in die einer Katze und erhöht Eure Bewegungsgeschwindigkeit in Katzengestalt 10 Sek. lang um 60%." }
entries[1852] = { ["name"] = "Zum Schweigen gebracht", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas ist ein GM-Tool, um Spieler stumm zu stellen. Dieser Zauber fungiert nur als visuelle Anzeige, damit der Spieler und der GM wissen, dass der Spieler gerade stumm gestellt ist." }
entries[1856] = { ["name"] = "Verschwinden", ["text"] = "Sofort 2 min Abklingzeit\n1 Aufladung\nErmöglicht es Euch, sofort zu verschwinden und so im Kampf in den Verstohlenheitsmodus überzugehen. Für die ersten 3 Sek. nach dem Verschwinden können weder Schaden noch schädliche Effekte die Verstohlenheit brechen. Bewegungseinschränkende Effekte werden beim Verschwinden entfernt." }
entries[1860] = { ["name"] = "Sicheres Fallen", ["text"] = "Verringert den Fallschaden." }
entries[1881] = { ["name"] = "Jungtier des Zaraschwarms beschwören" }
entries[1906] = { ["name"] = "Entkräftender Sturmangriff", ["text"] = "25 Meter Reichweite\nSofort\nStürmt auf einen Gegner zu, verursacht Schaden und verringert 8 Sek. lang seine Bewegungsgeschwindigkeit um 60%." }
entries[1936] = { ["name"] = "Teleport nach Ambossar" }
entries[1940] = { ["name"] = "Raketenschlag", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nFügt 1 Feuerschaden in einem Radius von 3 Metern zu." }
entries[1943] = { ["name"] = "Blutung", ["text"] = "25 Energie / 1 zu 5 Combopunkte Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der das Fleisch des Ziels aufreißt und regelmäßigen Blutungsschaden verursacht. Hält pro Combopunkt länger an.\n\n1 Punkt: [(67.3148% der Angriffskraft) * 2] Schaden im Verlauf von 8 Sek.\n2 Punkte: [(67.3148% der Angriffskraft) * 3] Schaden im Verlauf von 12 Sek.\n3 Punkte: [(67.3148% der Angriffskraft) * 4] Schaden im Verlauf von 16 Sek.\n4 Punkte: [(67.3148% der Angriffskraft) * 5] Schaden im Verlauf von 20 Sek.\n5 Punkte: [(67.3148% der Angriffskraft) * 6] Schaden im Verlauf von 24 Sek.\n[ 6 Punkte: [(67.3148% der Angriffskraft) * 7] Schaden im Verlauf von 28 Sek.] [ 7 Punkte: [(67.3148% der Angriffskraft) * 8] Schaden im Verlauf von 32 Sek.]" }
entries[1949] = { ["name"] = "Höllenfeuer", ["text"] = "1 Seelensplitter, plus 1 pro Sek.\nKanalisiert (Wirken in 10 sek.)\nBedeckt den Boden um Euch herum mit Höllenfeuer, das Euch selbst (40% der Zaubermacht) Feuerschaden und allen Gegnern in der Nähe alle 1 Sek. (40% der Zaubermacht) Feuerschaden zufügt.\n\nIhr könnt Euch während der Kanalisierung von 'Höllenfeuer' bewegen.\n\nKostet pro Sekunde 4 Seelensplitterfragmente." }
entries[1950] = { ["name"] = "Großer Schattenwichtel" }
entries[1953] = { ["name"] = "Blinzeln", ["text"] = "2% von Grundmana\nSofort 15 sek. Abklingzeit\n1 Aufladung\nTeleportiert Euch 20 Meter, oder bis Ihr auf ein Hindernis stoßt, vorwärts und befreit Euch von Betäubungs- und Bewegungsunfähigkeitseffekten." }
entries[1966] = { ["name"] = "Finte", ["text"] = "35 Energie\nSofort 15 sek. Abklingzeit\n1 Aufladung\nFührt ein Ausweichmanöver durch, das 6 Sek. lang den durch Flächeneffekte erlittenen Schaden um 40% verringert ." }
entries[2000] = { ["name"] = "Kopfschuss" }
entries[2006] = { ["name"] = "Auferstehung", ["text"] = "0.8% von Grundmana 40 Meter Reichweite\nWirken in 10 sek.\nBringt einen toten Verbündeten mit 35% Gesundheit und Mana ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
entries[2008] = { ["name"] = "Geist der Ahnen", ["text"] = "0.8% von Grundmana 40 Meter Reichweite\nWirken in 10 sek.\nLässt den Geist in den Körper zurückkehren und bringt ein totes Ziel mit 35% der maximalen Gesundheit und des maximalen Manas wieder ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
entries[2018] = { ["name"] = "Schmiedekunst", ["text"] = "Sofort\nErmöglicht einem Schmied, einfache Waffen und Rüstung herzustellen. Erfordert Stein und Metall, die mit der Bergbaufertigkeit gesammelt werden können." }
entries[2020] = { ["name"] = "Schmiedekunstlehrling" }
entries[2021] = { ["name"] = "Schmiedekunstgeselle" }
entries[2023] = { ["name"] = "Mana wiederherstellen", ["text"] = "Sofort 1 min Abklingzeit\nStellt 100 Mana wieder her." }
entries[2024] = { ["name"] = "Heiltrank", ["text"] = "Sofort 1 min Abklingzeit\nStellt 100 Gesundheit wieder her." }
entries[2050] = { ["name"] = "Segenswort: Epiphanie", ["text"] = "2.375% von Grundmana 40 Meter Reichweite\nSofort 1 min Abklingzeit\n1 Aufladung\nLässt ein Wunder geschehen und heilt einen Verbündeten um (1595.93% der Zaubermacht) Gesundheit. [ Glücksfall : Wenn Ihr 'Heilung' oder 'Blitzheilung' wirkt, wird die Abklingzeit um 6 Sek. verringert. ]" }
entries[2060] = { ["name"] = "Heilung", ["text"] = "2.28% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nEin effizienter Zauber, der einen Verbündeten um (972.861% der Zaubermacht) Gesundheit heilt." }
entries[2061] = { ["name"] = "Blitzheilung", ["text"] = "10% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nEin schneller Zauber, der einen Verbündeten um (341.04% der Zaubermacht) Gesundheit heilt." }
entries[2094] = { ["name"] = "Blenden", ["text"] = "15 Meter Reichweite\nSofort 2 min Abklingzeit\nBlendet das Ziel und lässt es 1 Min. lang desorientiert umherlaufen. Schaden kann den Effekt unterbrechen. Maximal 1 Ziel." }
entries[2096] = { ["name"] = "Gedankensicht", ["text"] = "1% von Grundmana Unbegrenzte Reichweite\nKanalisiert (Wirken in 1 min)\nErmöglicht dem Zaubernden, 1 Min. lang durch die Augen des Ziels zu sehen. Funktioniert nicht, wenn sich das Ziel in einer anderen Instanz oder auf einem anderen Kontinent befindet." }
entries[2098] = { ["name"] = "Tötung", ["text"] = "35 Energie / 1 zu 5 Combopunkte Nahkampfreichweite\nSofort\nFinishing-Move, der sich des Gegners entledigt. Verursacht Schaden pro Combopunkt:\n1 Punkt: [(44% der Angriffskraft)] Schaden\n2 Punkte: [(44% der Angriffskraft) * 2] Schaden\n3 Punkte: [(44% der Angriffskraft) * 3] Schaden\n4 Punkte: [(44% der Angriffskraft) * 4] Schaden\n5 Punkte: [(44% der Angriffskraft) * 5] Schaden\n[ 6 Punkte: [(44% der Angriffskraft) * 6] Schaden] [ 7 Punkte: [(44% der Angriffskraft) * 7] Schaden]" }
entries[2108] = { ["name"] = "Lederverarbeitung", ["text"] = "Sofort\nErmöglicht einem Lederverarbeiter, Leder- und Kettenrüstung herzustellen. Erfordert Lederfetzen und Bälge, die mit der Kürschnerfertigkeit gesammelt werden können." }
entries[2118] = { ["name"] = "Ausweichmeisterschaft", ["text"] = "100 Meter Reichweite\nSofort\nErhöht Eure Chance auszuweichen um 1%." }
entries[2119] = { ["name"] = "Naturwiderstand", ["text"] = "100 Meter Reichweite\nSofort\nNaturwiderstand um 4 erhöhen." }
entries[2120] = { ["name"] = "Flammenstoß", ["text"] = "1.5% von Grundmana 40 Meter Reichweite\nWirken in 3.5 sek.\nLässt eine Feuersäule niedergehen, die alle Gegner im Bereich verbrennt und ihnen so (119.34% der Zaubermacht) Feuerschaden zufügt sowie ihre Bewegungsgeschwindigkeit 8 Sek. lang um 20% verringert. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[2123] = { ["name"] = "Heilige Vorliebe", ["text"] = "Erhöht Eure 'Heilige Magie'-Fertigkeit um 4 und verringert Euren Schattenwiderstand um 2." }
entries[2139] = { ["name"] = "Gegenzauber", ["text"] = "2% von Grundmana 40 Meter Reichweite\nSofort 24 sek. Abklingzeit\nKontert das Zauberwirken des Gegners und verhindert so 5 Sek. lang, dass ein Zauber dieser Art gewirkt werden kann." }
entries[2140] = { ["name"] = "Stasis" }
entries[2147] = { ["name"] = "Besserung", ["text"] = "Unbegrenzte Reichweite\nSofort\nRegelmäßige Heilung." }
entries[2148] = { ["name"] = "Regelmäßiger Schattensturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nWirkt in regelmäßigen Abständen Schattensturm." }
entries[2149] = { ["name"] = "Handgenähte Lederstiefel", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Leder (2), Grober Faden\nBeruf:\nLederverarbeitung (1)\n\nWird beim Anlegen gebunden\nFüße Leder\n2 Rüstung\nHaltbarkeit 35 / 35\n2" }
