entries[2158] = { ["name"] = "Feine Lederstiefel", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Leder (7), Grober Faden (2)\nOptionale Reagenzien:\n[] (#31)\nBeute von:\nWeltkreaturen\n\nSchatz:\nWeltbeute\n\nSammeln von:\nWeltvorkommen\n\nFeine Lederstiefel\nWird beim Anlegen gebunden\nFüße Leder\n2 Rüstung\n+3 [Beweglichkeit oder Intelligenz]Haltbarkeit 45 / 45\n6" }
