entries[2637] = { ["name"] = "Überwintern", ["text"] = "1.2% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nZwingt das gegnerische Ziel, bis zu 40 Sek. lang zu schlafen. Jeglicher Schaden führt dazu, dass das Ziel erwacht. Es kann immer nur jeweils ein Ziel in Winterschlaf versetzt werden. Wirkt nur bei Wildtieren und Drachkin." }
entries[2639] = { ["name"] = "Essen", ["text"] = "Sofort\nStellt 21 Sek. lang ( 53 * 21 / 5) Gesundheit und 212 Mana wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[2641] = { ["name"] = "Begleiter freigeben", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nSchickt Euer Tier zeitweise fort. Ihr könnt es später wieder herbeirufen." }
entries[2643] = { ["name"] = "Mehrfachschuss", ["text"] = "40 Fokus 40 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nFeuert eine Geschosssalve ab, die alle Gegner innerhalb von 8 Metern um Euer aktuelles Ziel trifft und ihnen (75.6% der Angriffskraft) körperlichen Schaden zufügt. [ Raubtierhiebe : Außerdem wird 'Raubtierhiebe' ausgelöst ] Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. [ Gezielter Schuss : Erzeugt pro getroffenem Ziel 5 Fokus. ]" }
entries[2645] = { ["name"] = "Geisterwolf", ["text"] = "Sofort\nVerwandelt Euch in einen Geisterwolf, wodurch sich Eure Bewegungsgeschwindigkeit um [ Winde von Al'Akir : 30 / 30]% erhöht. Zudem wird verhindert, dass Eure Bewegungsgeschwindigkeit unter 100% verringert wird." }
entries[2649] = { ["name"] = "Knurren", ["text"] = "30 Meter Reichweite\nSofort 8 sek. Abklingzeit\nEuer Begleiter knurrt das Ziel an und erzeugt Bedrohung, was es dazu bringt, den Begleiter anzugreifen." }
entries[2656] = { ["name"] = "Bergbautagebuch", ["text"] = "Sofort\nHier erhaltet Ihr Informationen über Bergbaufertigkeiten, Vorkommen und Spezialisierungen. Außerdem könnt Ihr Eure Bergbauausrüstung verwalten." }
entries[2657] = { ["name"] = "Kupfer verhütten", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKupfererz\nErmöglicht dem Minenarbeiter, einen Brocken Kupfererz zu einem Kupferbarren zu verhütten. Das Verhütten von Kupfer erfordert eine Schmiede.\nBeruf:\nBergbau (1)\n\nKupferbarren\nHandwerksmaterial" }
