entries[2818] = { ["name"] = "Tödliches Gift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. [(11.374% der Angriffskraft) * 12 / 2] Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort (8.14% der Angriffskraft) Naturschaden." }
entries[2823] = { ["name"] = "Tödliches Gift", ["text"] = "Wirken in 1.5 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. [(11.374% der Angriffskraft) * 12 / 2] Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort (8.14% der Angriffskraft) Naturschaden.\n(Procchance: 30%)" }
